const topics = require('./topics-4-7.js');
const baseFields = ['route','type','title','summary','contentMd','frontMatter','id','img','imgFile','video','videoids','hide','authLevel'];
let errors = [];
let stats = { talks: 0, notebooks: 0, notes: 0, labs: 0, cells: 0, steps: 0 };

function checkBase(obj, path) {
  for (const f of baseFields) {
    if (!(f in obj)) errors.push(path + ' missing field: ' + f);
  }
  if (!('videoid' in (obj.videoids||{}))) errors.push(path + ' videoids missing videoid');
  if (!('videoIds' in (obj.videoids||{}))) errors.push(path + ' videoids missing videoIds');
}

topics.forEach(t => {
  checkBase(t, t.id);
  if (!t.los) { errors.push(t.id + ' missing los'); return; }
  t.los.forEach(unit => {
    checkBase(unit, t.id+'/'+unit.id);
    if (!unit.los) { errors.push(unit.id + ' missing los'); return; }
    unit.los.forEach(item => {
      checkBase(item, t.id+'/'+unit.id+'/'+item.id);
      if (item.type === 'talk') {
        stats.talks++;
        if (!('pdf' in item)) errors.push(item.id + ' talk missing pdf');
        if (!('pdfFile' in item)) errors.push(item.id + ' talk missing pdfFile');
        if (item.frontMatter.marp !== 'true') errors.push(item.id + ' talk missing marp frontMatter');
        if (!item.contentMd.startsWith('---\nmarp: true')) errors.push(item.id + ' contentMd missing marp header');
      }
      if (item.type === 'notebook') {
        stats.notebooks++;
        if (!item.cells) errors.push(item.id + ' notebook missing cells');
        else {
          stats.cells += item.cells.length;
          item.cells.forEach(c => {
            if (!c.cellType) errors.push(item.id + '/' + c.id + ' missing cellType');
            if (!('source' in c)) errors.push(item.id + '/' + c.id + ' missing source');
            if (!('outputs' in c)) errors.push(item.id + '/' + c.id + ' missing outputs');
            if (!('executionCount' in c)) errors.push(item.id + '/' + c.id + ' missing executionCount');
            if (!('metadata' in c)) errors.push(item.id + '/' + c.id + ' missing metadata');
            if (!c.id) errors.push(item.id + ' cell missing id');
          });
        }
        if (!item.kernelLanguage) errors.push(item.id + ' missing kernelLanguage');
      }
      if (item.type === 'lab') {
        stats.labs++;
        if (!('pdf' in item)) errors.push(item.id + ' lab missing pdf');
        if (!('pdfFile' in item)) errors.push(item.id + ' lab missing pdfFile');
        if (!item.los) errors.push(item.id + ' lab missing los');
        else {
          item.los.forEach(step => {
            stats.steps++;
            if (step.type !== 'step') errors.push(step.id + ' not type step');
            if (!step.shortTitle) errors.push(step.id + ' missing shortTitle');
            if (!('contentHtml' in step)) errors.push(step.id + ' missing contentHtml');
          });
        }
      }
      if (item.type === 'note') stats.notes++;
    });
  });
});

console.log('Stats:', JSON.stringify(stats));
if (errors.length) {
  console.log('ERRORS:');
  errors.forEach(e => console.log('  -', e));
} else {
  console.log('All validations passed!');
}
